os.chdir('/home/wijnandb/sites/github/15-a-day-hugo/content/books/')

aantal = 0
for book in books:
    aantal += 1

    # create slug to use as a filename
    slug = slugify(book[1])

    
    d = date.today() - timedelta(days=4*aantal)

    # add "book" to tags and create list of tags, no empty tags
    tagthis = ["book"]
    tags = book[2].split(", ")
    tags = list(filter(None, tags))
    for tag in tags:
        tagthis.append(tag)

    # create a filtered list of authors, no empty strings, no doubles
    writers = book[3].split(":")
    writers = list(filter(None, writers))
    distinctwriters = set(writers)
    authors = list(distinctwriters)

    storelink = "https://www.amazon.com/dp/" + book[0]
    affiliatelink = storelink + "?tag=prcptm-20"

    cover = "/images/bookcovers/small/" + book[0] +".jpg"
    # create the front matter for the markdown files
    bookfile =  open('%s.md' % slug, 'w')
    bookfile.write('---\n')
    bookfile.write('draft: true\n')
    bookfile.write('layout: book\n')
    bookfile.write('title: "%s"\n' % book[1])
    bookfile.write('template: book\n')
    bookfile.write('date: %s\n' % d)
    bookfile.write('cover: %s\n' % cover)
    bookfile.write('tags:  %s\n' % tagthis)
    bookfile.write('authors: %s\n' % authors)
    bookfile.write('largecover: "%s"\n' % book[6])
    bookfile.write('readlink: "%s"\n' % book[5])
    bookfile.write('ASIN: %s\n' % book[0])
    #bookfile.write('storelink: %s\n' % storelink)
    bookfile.write('affiliatelink: %s\n' % affiliatelink)
    bookfile.write('---\n\n')

    bookfile.write('\nThe book \n')

print(aantal)